// Normalize every Sent-sheet row into the dashboard's expected shape.
// Produces ONE item carrying the full batch. No emails are sent, sheet is not modified.
function s(v){ return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(i => i.json || {});
const norm = rows
  .filter(r => s(r.email))
  .map(r => ({
    email: s(r.email).toLowerCase(),
    companyName: s(r.business_name),
    business_name: s(r.business_name),
    website: s(r.website),
    country: s(r.country),
    city: s(r.city),
    niche: s(r.niche),
    language: s(r.language),
    subject: s(r.subject),
    message_text: s(r.message_text),
    follow_up_subject: s(r.follow_up_subject),
    follow_up_text: s(r.follow_up_text),
    status: s(r.status),
    timestamp_sent: s(r.timestamp_sent),
    follow_up_due_date: s(r.follow_up_due_date),
    follow_up_sent_at: s(r.follow_up_sent_at)
  }));
return [{ json: {
  source: 'google_sheets_sync',
  workflowName: 'KlijentiTrazenjeAutomatizacija_v10_jezici',
  syncedAt: new Date().toISOString(),
  rowCount: norm.length,
  rows: norm
} }];
